package got.world.genlayer; public class GOTGenLayerBiomeSubtypes extends GOTGenLayer {private final GOTGenLayer variantsLayer;public GOTGenLayerBiomeSubtypes(long s,GOTGenLayer biome,GOTGenLayer variants){super(s);gotParent=biome;variantsLayer=variants;}public void initWorldGenSeed(long s){super.initWorldGenSeed(s);variantsLayer.initWorldGenSeed(s);}public int[] getInts(int x,int z,int w,int h){int[] b=gotParent.getInts(x,z,w,h),v=variantsLayer.getInts(x,z,w,h),o=b.clone();for(int i=0;i<o.length;i++)if(v[i]%97==0)o[i]=b[i];return o;}}